static boolean isMinHeap(int[] a, int n) {   // a[1..n]
    for (int k = 2; k <= n; k++)
        if (a[k / 2] > a[k]) return false;
    return true;
}

void add(int x) {                         // Θ(log N)
    h[++n] = x;
    swim(n);
}
void swim(int k) {
    while (k > 1 && h[k / 2] > h[k]) { swap(k, k / 2); k = k / 2; }
}
int removeSmallest() {                    // Θ(log N)
    int min = h[1];
    h[1] = h[n--];                        // last item to the root
    sink(1);
    return min;
}
void sink(int k) {
    while (2 * k <= n) {
        int j = 2 * k;
        if (j < n && h[j + 1] < h[j]) j++; // the SMALLER child
        if (h[k] <= h[j]) break;
        swap(k, j);
        k = j;
    }
}

void preorder(Node t)  { if (t == null) return; visit(t); preorder(t.left); preorder(t.right); }
void inorder(Node t)   { if (t == null) return; inorder(t.left); visit(t); inorder(t.right); }
void postorder(Node t) { if (t == null) return; postorder(t.left); postorder(t.right); visit(t); }
void levelOrder(Node t) {
    Queue<Node> q = new ArrayDeque<>();
    if (t != null) q.add(t);
    while (!q.isEmpty()) {
        Node x = q.remove();
        visit(x);
        if (x.left != null) q.add(x.left);
        if (x.right != null) q.add(x.right);
    }
}

