static int kth(int[] h, int n, int k) {
    PriorityQueue<Integer> pq = new PriorityQueue<>((x, y) -> Integer.compare(h[x], h[y]));
    pq.add(1);
    int r = -1;
    for (int i = 0; i < k; i++) {
        int idx = pq.poll();
        r = h[idx];
        if (2 * idx <= n) pq.add(2 * idx);
        if (2 * idx + 1 <= n) pq.add(2 * idx + 1);
    }
    return r;
}

void add(int x) {
    if (lo.isEmpty() || x <= lo.peek()) lo.add(x); else hi.add(x);
    if (lo.size() > hi.size() + 1) hi.add(lo.poll());
    else if (hi.size() > lo.size()) lo.add(hi.poll());
}
int getMedian() { return lo.peek(); }
int removeMedian() {
    int m = lo.poll();
    if (hi.size() > lo.size()) lo.add(hi.poll());
    return m;
}

static Node build(int[] a, int lo, int hi) {
    if (lo > hi) return null;
    int mid = (lo + hi) / 2;
    Node t = new Node(a[mid]);
    t.left = build(a, lo, mid - 1);
    t.right = build(a, mid + 1, hi);
    return t;
}

static int size(S t) {                      // t and all its later siblings
    if (t == null) return 0;
    return 1 + size(t.child) + size(t.sib);
}
static int height(S t) {                    // max height among t and its siblings
    if (t == null) return -1;
    return Math.max(1 + height(t.child), height(t.sib));
}
static int maxDeg(S t) {
    if (t == null) return 0;
    int d = 0;
    for (S c = t.child; c != null; c = c.sib) d++;
    return Math.max(d, Math.max(maxDeg(t.child), maxDeg(t.sib)));
}

static int i = 0;
static Node rebuild(int[] pre, int lo, int hi) {   // keys allowed in [lo, hi]
    if (i >= pre.length || pre[i] < lo || pre[i] > hi) return null;
    int v = pre[i++];
    Node t = new Node(v);
    t.left = rebuild(pre, lo, v - 1);
    t.right = rebuild(pre, v + 1, hi);
    return t;
}
